// sealed — raw byte arrays, generated by `tool/npd_pack.dart`
// from `tool/npd_guard.recipe.json` (gitignored).
//
// Each array is meaningful only after `cloak::unseal` runs on it.
// Static scanners (`strings libnpd_guard.a`) see random noise;
// every array is also wrapped in `obfstr::obfbytes!` so even a
// `.rodata` dump never contains a sealed payload as a contiguous
// run.
//
// DO NOT HAND-EDIT. Re-run `dart run tool/npd_pack.dart` after
// changing the recipe.
// ─────────────────────────────────────────────────────────────

use obfstr::obfbytes;

/// Index enum — opaque u32 crossing the FFI boundary. Keep in
/// sync with `lib/orbit_guard/orbit_guard.dart::SealedIndex`.
#[repr(u32)]
#[derive(Copy, Clone, Debug)]
#[allow(dead_code)]
pub enum Idx {
    Endpoint = 0,
    GcdBase = 1,
    AttributionKey = 2,
    MessagingProject = 3,
    OneLinkHost = 4,
    UaProduct = 10,
    UaPlatformPrefix = 11,
    UaPlatformSuffix = 12,
    UaEngine = 13,
    UaMobileToken = 14,
    SafariVersion = 15,
    SafariTail = 16,
    JsOrbitShell = 30,
}

impl Idx {
    pub fn from_raw(raw: u32) -> Option<Self> {
        Some(match raw {
            0 => Idx::Endpoint,
            1 => Idx::GcdBase,
            2 => Idx::AttributionKey,
            3 => Idx::MessagingProject,
            4 => Idx::OneLinkHost,
            10 => Idx::UaProduct,
            11 => Idx::UaPlatformPrefix,
            12 => Idx::UaPlatformSuffix,
            13 => Idx::UaEngine,
            14 => Idx::UaMobileToken,
            15 => Idx::SafariVersion,
            16 => Idx::SafariTail,
            30 => Idx::JsOrbitShell,
            _ => return None,
        })
    }
}

pub fn fetch(idx: Idx) -> Vec<u8> {
    match idx {
        Idx::Endpoint => bytes_endpoint(),
        Idx::GcdBase => bytes_gcd_base(),
        Idx::AttributionKey => bytes_attribution_key(),
        Idx::MessagingProject => bytes_messaging_project(),
        Idx::OneLinkHost => bytes_one_link_host(),
        Idx::UaProduct => bytes_ua_product(),
        Idx::UaPlatformPrefix => bytes_ua_platform_prefix(),
        Idx::UaPlatformSuffix => bytes_ua_platform_suffix(),
        Idx::UaEngine => bytes_ua_engine(),
        Idx::UaMobileToken => bytes_ua_mobile_token(),
        Idx::SafariVersion => bytes_safari_version(),
        Idx::SafariTail => bytes_safari_tail(),
        Idx::JsOrbitShell => bytes_js_orbit_shell(),
    }
}

